package com.vstream.Vidiserver;

/** The Memoryq Radio Server installer served at /install.sh (made from install.sh by the update script - do not edit by hand). */
final class InstallScript {

    private InstallScript() {
    }

    static final String JS = ""
            + "#!/bin/bash\n"
            + "# Memoryq Radio Server - installer.\n"
            + "#   curl -fsSL @@BASE@@/install.sh | sudo bash -s -- MQ1.your-install-key\n"
            + "# 1. Checks this server (system, memory, disk, ports, the internet) - nothing is changed if a check fails.\n"
            + "# 2. Checks the install key with Memoryq (the key is not used up yet).\n"
            + "# 3. Activates the licence: from now on it belongs to this server's IP address. To move to another server, make a\n"
            + "#    new install command in your account at @@BASE@@/licence.\n"
            + "# 4. Installs the check-in service (every 5 minutes: online, version, load - no listener data, no passwords) and mqctl.\n"
            + "# The radio server itself (Studio, AutoDJ, DJ Pro) is installed by the next version of this installer.\n"
            + "set -uo pipefail\n"
            + "\n"
            + "BASE=\"@@BASE@@\"\n"
            + "VERSION=\"@@VERSION@@\"\n"
            + "KEY=\"${1:-${MQ_KEY:-}}\"\n"
            + "ROOT=\"${MQ_ROOT:-}\"            # tests only: install under another folder\n"
            + "DRY=\"${MQ_DRYRUN:-0}\"          # tests only: no root, no systemd\n"
            + "ETC=\"$ROOT/etc/memoryq\"\n"
            + "LIB=\"$ROOT/var/lib/memoryq\"\n"
            + "SBIN=\"$ROOT/usr/local/sbin\"\n"
            + "\n"
            + "B=\"\\033[1m\"; G=\"\\033[32m\"; R=\"\\033[31m\"; Y=\"\\033[33m\"; N=\"\\033[0m\"\n"
            + "[ -t 1 ] || { B=\"\"; G=\"\"; R=\"\"; Y=\"\"; N=\"\"; }\n"
            + "ok()   { echo -e \"  ${G}OK${N}    $*\"; }\n"
            + "warn() { echo -e \"  ${Y}NOTE${N}  $*\"; WARNINGS=$((WARNINGS+1)); }\n"
            + "bad()  { echo -e \"  ${R}FAIL${N}  $*\"; FAILS=$((FAILS+1)); }\n"
            + "step() { echo; echo -e \"${B}== $*${N}\"; }\n"
            + "FAILS=0; WARNINGS=0\n"
            + "\n"
            + "echo -e \"${B}Memoryq Radio Server installer $VERSION${N}  ($BASE)\"\n"
            + "if [ -z \"$KEY\" ] || [[ \"$KEY\" != MQ1.* ]]; then\n"
            + "  echo \"Use the install command from your account: $BASE/licence\"\n"
            + "  echo \"  curl -fsSL $BASE/install.sh | sudo bash -s -- MQ1.your-install-key\"\n"
            + "  exit 2\n"
            + "fi\n"
            + "\n"
            + "# ---------------------------------------------------------------- 1. this server\n"
            + "step \"1/4 Checking this server\"\n"
            + "if [ \"$DRY\" != 1 ] && [ \"$(id -u)\" != 0 ]; then bad \"run it as root: put sudo in front (sudo bash -s -- ...)\"; fi\n"
            + "OS_ID=\"\"; OS_VER=\"\"; OS_NAME=\"unknown\"\n"
            + "if [ -f /etc/os-release ]; then   # read in a subshell: os-release has its own VERSION, NAME...\n"
            + "  OS_ID=\"$(. /etc/os-release; echo \"${ID:-}\")\"; OS_VER=\"$(. /etc/os-release; echo \"${VERSION_ID:-}\")\"\n"
            + "  OS_NAME=\"$(. /etc/os-release; echo \"${PRETTY_NAME:-${ID:-} ${VERSION_ID:-}}\")\"\n"
            + "fi\n"
            + "case \"$OS_ID:$OS_VER\" in\n"
            + "  ubuntu:22.04|ubuntu:24.04|debian:12) ok \"system: $OS_NAME\" ;;\n"
            + "  ubuntu:*|debian:*) warn \"system: $OS_NAME - tested on Ubuntu 22.04 / 24.04 and Debian 12; it may still work\" ;;\n"
            + "  *) if [ \"$DRY\" = 1 ]; then warn \"system: $OS_NAME (test run)\"; else bad \"system: $OS_NAME - needs Ubuntu 22.04 / 24.04 or Debian 12\"; fi ;;\n"
            + "esac\n"
            + "ARCH=\"$(uname -m)\"\n"
            + "case \"$ARCH\" in x86_64|amd64|aarch64|arm64) ok \"processor: $ARCH, $(nproc 2>/dev/null || echo ?) core(s)\" ;; *) bad \"processor: $ARCH - needs 64-bit (x86_64 or ARM64)\" ;; esac\n"
            + "if [ \"$DRY\" != 1 ]; then\n"
            + "  if command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ]; then ok \"systemd is running\"; else bad \"systemd is needed (a normal VPS has it; containers often do not)\"; fi\n"
            + "fi\n"
            + "MEM_MB=$(( $(awk '/MemTotal/{print $2}' /proc/meminfo 2>/dev/null || echo 0) / 1024 ))\n"
            + "if [ \"$MEM_MB\" -ge 1800 ]; then ok \"memory: ${MEM_MB} MB\"; elif [ \"$MEM_MB\" -ge 900 ]; then warn \"memory: ${MEM_MB} MB - enough for a few channels; 2 GB or more is better\"; else bad \"memory: ${MEM_MB} MB - at least 1 GB is needed\"; fi\n"
            + "DISK_AT=\"${ROOT:-/}\"; while [ ! -d \"$DISK_AT\" ]; do DISK_AT=\"$(dirname \"$DISK_AT\")\"; done\n"
            + "DISK_GB=$(df -Pk \"$DISK_AT\" 2>/dev/null | awk 'NR==2{print int($4/1048576)}')\n"
            + "if [ \"${DISK_GB:-0}\" -ge 20 ]; then ok \"free disk: ${DISK_GB} GB\"; elif [ \"${DISK_GB:-0}\" -ge 8 ]; then warn \"free disk: ${DISK_GB} GB - music needs room; 20 GB or more is better\"; else bad \"free disk: ${DISK_GB:-0} GB - at least 8 GB is needed\"; fi\n"
            + "for t in curl awk sed; do command -v \"$t\" >/dev/null 2>&1 || bad \"$t is missing (apt-get install -y $t)\"; done\n"
            + "if curl -fsS -m 15 -o /dev/null \"$BASE/api/licence/prices\"; then ok \"reaches $BASE\"; else bad \"cannot reach $BASE - check the internet and the firewall (outgoing HTTPS)\"; fi\n"
            + "\n"
            + "# ---------------------------------------------------------------- 2. the key\n"
            + "step \"2/4 Checking the install key\"\n"
            + "post() { curl -sS -m 30 -X POST \"$@\"; }\n"
            + "field() { printf '%s' \"$1\" | sed -n \"s/.*\\\"$2\\\":\\\"\\{0,1\\}\\([^\\\",}]*\\)\\\"\\{0,1\\}.*/\\1/p\" | head -1; }\n"
            + "CHECK=\"$(post --data-urlencode \"key=$KEY\" \"$BASE/api/licence/check\" 2>&1)\"\n"
            + "if printf '%s' \"$CHECK\" | grep -q '\"ok\":true'; then\n"
            + "  LIC=$(field \"$CHECK\" licence); KIND=$(field \"$CHECK\" kind); CH=$(field \"$CHECK\" channels)\n"
            + "  P1=$(field \"$CHECK\" firstPort); P2=$(field \"$CHECK\" lastPort); MYIP=$(field \"$CHECK\" ip)\n"
            + "  ok \"licence #$LIC: $KIND, $CH channel(s), streaming ports $P1-$P2\"\n"
            + "  ok \"this server's address (as Memoryq sees it): $MYIP\"\n"
            + "else\n"
            + "  ERR=$(field \"$CHECK\" error); bad \"${ERR:-could not check the key: $CHECK}\"\n"
            + "fi\n"
            + "\n"
            + "if [ \"$FAILS\" = 0 ]; then\n"
            + "  NEED=$(( 768 + ${CH:-1} * 40 ))\n"
            + "  if [ \"$MEM_MB\" -lt \"$NEED\" ]; then warn \"for $CH channels about $NEED MB of memory is recommended (this server has $MEM_MB MB)\"; fi\n"
            + "  BUSY=\"\"\n"
            + "  if command -v ss >/dev/null 2>&1; then\n"
            + "    for p in $(seq \"$P1\" \"$P2\"); do ss -ltn 2>/dev/null | awk '{print $4}' | grep -qE \"[:.]$p\\$\" && BUSY=\"$BUSY $p\"; done\n"
            + "    if [ -z \"$BUSY\" ]; then ok \"streaming ports $P1-$P2 are free\"; else bad \"these streaming ports are in use by another program:$BUSY\"; fi\n"
            + "    WEB=$(ss -ltnp 2>/dev/null | grep -E '[:.](80|443) ' | grep -v caddy | head -1)\n"
            + "    if [ -n \"$WEB\" ]; then warn \"another web server uses port 80/443 - the radio server's HTTPS needs them (stop Apache/nginx before the radio install)\"; else ok \"ports 80 and 443 are free for HTTPS\"; fi\n"
            + "  fi\n"
            + "fi\n"
            + "\n"
            + "if [ \"$FAILS\" -gt 0 ]; then\n"
            + "  echo; echo -e \"${R}${B}Stopped: $FAILS check(s) failed - nothing was changed on this server and the install key was not used.${N}\"\n"
            + "  echo \"Fix the lines marked FAIL and run the same command again.\"\n"
            + "  exit 1\n"
            + "fi\n"
            + "\n"
            + "# ---------------------------------------------------------------- 3. activate\n"
            + "step \"3/4 Activating the licence on this server\"\n"
            + "HOSTN=\"$(hostname -f 2>/dev/null || hostname)\"\n"
            + "ACT=\"$(post --data-urlencode \"key=$KEY\" --data-urlencode \"host=$HOSTN\" --data-urlencode \"os=$OS_NAME $ARCH, ${MEM_MB} MB, ${DISK_GB} GB free\" \\\n"
            + "  --data-urlencode \"version=$VERSION\" \"$BASE/api/licence/activate\" 2>&1)\"\n"
            + "SECRET=$(field \"$ACT\" secret)\n"
            + "if [ -z \"$SECRET\" ] || [[ \"$SECRET\" != MQS.* ]]; then\n"
            + "  ERR=$(field \"$ACT\" error); echo -e \"  ${R}FAIL${N}  ${ERR:-activation failed: $ACT}\"; exit 1\n"
            + "fi\n"
            + "umask 077\n"
            + "mkdir -p \"$ETC\" \"$LIB\" \"$SBIN\"\n"
            + "cat > \"$ETC/licence.conf\" <<EOF\n"
            + "# Memoryq Radio Server licence - keep private. Made $(date -u '+%Y-%m-%d %H:%M UTC') on $HOSTN.\n"
            + "MQ_BASE=\"$BASE\"\n"
            + "MQ_LICENCE=$LIC\n"
            + "MQ_KIND=\"$KIND\"\n"
            + "MQ_CHANNELS=$CH\n"
            + "MQ_FIRST_PORT=$P1\n"
            + "MQ_LAST_PORT=$P2\n"
            + "MQ_VERSION=\"$VERSION\"\n"
            + "MQ_SECRET=\"$SECRET\"\n"
            + "EOF\n"
            + "chmod 600 \"$ETC/licence.conf\"\n"
            + "ok \"licence #$LIC is now tied to this server ($MYIP)\"\n"
            + "\n"
            + "# ---------------------------------------------------------------- 4. check-in service and mqctl\n"
            + "step \"4/4 Check-in service and mqctl\"\n"
            + "cat > \"$SBIN/mq-checkin\" <<'EOF'\n"
            + "#!/bin/bash\n"
            + "# Tells Memoryq this server is online (every 5 minutes): version, uptime, load, memory, disk. No listener data, no passwords.\n"
            + "CONF=\"${MQ_CONF:-/etc/memoryq/licence.conf}\"; LIB=\"${MQ_LIB:-/var/lib/memoryq}\"\n"
            + ". \"$CONF\" || exit 1\n"
            + "UP=$(awk '{print int($1/3600)}' /proc/uptime 2>/dev/null); LOAD=$(cut -d' ' -f1 /proc/loadavg 2>/dev/null)\n"
            + "MEMF=$(awk '/MemAvailable/{print int($2/1024)}' /proc/meminfo 2>/dev/null); DISKF=$(df -Pk / | awk 'NR==2{print int($4/1048576)}')\n"
            + "STATS=\"uptime ${UP}h, load ${LOAD}, ${MEMF} MB free, ${DISKF} GB disk free\"\n"
            + "R=$(curl -sS -m 20 -X POST -H \"Authorization: Bearer $MQ_SECRET\" --data-urlencode \"version=$MQ_VERSION\" --data-urlencode \"stats=$STATS\" \"$MQ_BASE/api/licence/checkin\" 2>&1)\n"
            + "mkdir -p \"$LIB\"; printf '%s %s\\n' \"$(date -u '+%Y-%m-%d %H:%M:%S UTC')\" \"$R\" > \"$LIB/last-checkin\"\n"
            + "case \"$R\" in *'\"ok\":true'*) exit 0 ;; *) echo \"$R\" | sed -n 's/.*\"error\":\"\\([^\"]*\\)\".*/\\1/p' | logger -t memoryq 2>/dev/null; exit 1 ;; esac\n"
            + "EOF\n"
            + "cat > \"$SBIN/mqctl\" <<'EOF'\n"
            + "#!/bin/bash\n"
            + "# mqctl status | checkin | update | uninstall\n"
            + "CONF=\"${MQ_CONF:-/etc/memoryq/licence.conf}\"; LIB=\"${MQ_LIB:-/var/lib/memoryq}\"\n"
            + "[ -r \"$CONF\" ] || { echo \"No licence here (or run with sudo). Install: see the Memoryq account page.\"; exit 1; }\n"
            + ". \"$CONF\"\n"
            + "case \"${1:-status}\" in\n"
            + "  status)\n"
            + "    echo \"Memoryq Radio Server $MQ_VERSION - licence #$MQ_LICENCE ($MQ_KIND, $MQ_CHANNELS channel(s), ports $MQ_FIRST_PORT-$MQ_LAST_PORT)\"\n"
            + "    if [ -f \"$LIB/last-checkin\" ]; then\n"
            + "      L=$(cat \"$LIB/last-checkin\"); echo \"Last check-in: ${L%% \\{*}\"\n"
            + "      echo \"$L\" | sed -n 's/.*\"state\":\"\\([^\"]*\\)\".*/Licence: \\1/p'\n"
            + "      echo \"$L\" | sed -n 's/.*\"error\":\"\\([^\"]\\{1,\\}\\)\".*/Problem: \\1/p'\n"
            + "      echo \"$L\" | sed -n 's/.*\"message\":\"\\([^\"]\\{1,\\}\\)\".*/Note: \\1/p'\n"
            + "    else echo \"No check-in yet.\"; fi ;;\n"
            + "  checkin) \"$(dirname \"$0\")/mq-checkin\" && echo \"Checked in.\" || { echo \"Check-in failed:\"; cat \"$LIB/last-checkin\"; exit 1; } ;;\n"
            + "  update) echo \"Updates arrive with the radio server install (next version of the installer). For now: run the install command again from your account.\" ;;\n"
            + "  uninstall)\n"
            + "    systemctl disable --now memoryq-checkin.timer 2>/dev/null; rm -f /etc/systemd/system/memoryq-checkin.* \"$(dirname \"$0\")/mq-checkin\"\n"
            + "    rm -rf /etc/memoryq \"$LIB\"; systemctl daemon-reload 2>/dev/null; echo \"Removed. The licence stays in your account (make a new install command to use it again).\"\n"
            + "    rm -f \"$0\" ;;\n"
            + "  *) echo \"mqctl status | checkin | update | uninstall\" ;;\n"
            + "esac\n"
            + "EOF\n"
            + "chmod 755 \"$SBIN/mq-checkin\" \"$SBIN/mqctl\"\n"
            + "if [ \"$DRY\" = 1 ]; then\n"
            + "  MQ_CONF=\"$ETC/licence.conf\" MQ_LIB=\"$LIB\" \"$SBIN/mq-checkin\" && ok \"first check-in done (test run: no systemd timer)\" || warn \"the first check-in failed: $(cat \"$LIB/last-checkin\")\"\n"
            + "else\n"
            + "  cat > /etc/systemd/system/memoryq-checkin.service <<EOF\n"
            + "[Unit]\n"
            + "Description=Memoryq licence check-in\n"
            + "After=network-online.target\n"
            + "[Service]\n"
            + "Type=oneshot\n"
            + "ExecStart=$SBIN/mq-checkin\n"
            + "EOF\n"
            + "  cat > /etc/systemd/system/memoryq-checkin.timer <<EOF\n"
            + "[Unit]\n"
            + "Description=Memoryq licence check-in every 5 minutes\n"
            + "[Timer]\n"
            + "OnBootSec=1min\n"
            + "OnUnitActiveSec=5min\n"
            + "Persistent=true\n"
            + "[Install]\n"
            + "WantedBy=timers.target\n"
            + "EOF\n"
            + "  systemctl daemon-reload\n"
            + "  systemctl enable --now memoryq-checkin.timer >/dev/null 2>&1\n"
            + "  if \"$SBIN/mq-checkin\"; then ok \"first check-in done; it repeats every 5 minutes\"; else warn \"the first check-in failed: $(cat \"$LIB/last-checkin\")\"; fi\n"
            + "fi\n"
            + "ok \"mqctl installed: sudo mqctl status\"\n"
            + "\n"
            + "echo\n"
            + "echo -e \"${G}${B}DONE.${N} Licence #$LIC ($KIND, $CH channel(s), ports $P1-$P2) is active on this server.\"\n"
            + "[ \"$WARNINGS\" -gt 0 ] && echo \"  $WARNINGS note(s) above - worth a look.\"\n"
            + "echo \"  See it any time:  sudo mqctl status      Your account: $BASE/licence\"\n"
            + "echo \"  Moving to another server later? Make a new install command in your account (this one then stops).\"\n";
}